        for field, val in overrides.items():
            if not getattr(place, field, None):
                setattr(place, field, val)

        district = place.district
        d_slug = district.slug if district else ''
        stats = DistrictStats.objects.filter(district_id=place.district_id).first()
        culture = DistrictCulture.objects.filter(district_id=place.district_id).first()

        d_name_en = getattr(district, 'name_en', None) or getattr(district, 'name', '') or ''
        d_name_ne = getattr(district, 'name_ne', None) or d_name_en
        p_title_en = getattr(place, 'title_en', None) or getattr(place, 'title', '') or ''
        p_title_ne = getattr(place, 'title_ne', None) or p_title_en

        if not place.location_en and d_name_en:
            hq_en = getattr(stats, 'headquarters_en', None) or getattr(stats, 'headquarters', '') if stats else ''
            place.location_en = f"{d_name_en} District" if not hq_en else f"{d_name_en} ({hq_en.split('(')[0].strip()})"
        if not place.location_ne and d_name_ne:
            place.location_ne = f"{d_name_ne} जिल्ला"

        if not place.elevation_en and stats and stats.elevation:
            place.elevation_en = stats.elevation
        if not place.elevation_ne and stats and stats.elevation:
            place.elevation_ne = stats.elevation

        if not place.best_time_to_visit_en:
            place.best_time_to_visit_en = 'September – November & February – April'
        if not place.best_time_to_visit_ne:
            place.best_time_to_visit_ne = 'असोज – मंसिर र फागुन – वैशाख'

        w_en, w_ne = DEFAULT_WEATHER.get(d_slug, ('24°C • Pleasant', '२४°से • सन्तुलित मौसम'))
        if not place.weather_summary_en:
            place.weather_summary_en = w_en
        if not place.weather_summary_ne:
            place.weather_summary_ne = w_ne

        if culture:
            if not place.festivals_en:
                place.festivals_en = getattr(culture, 'festivals_en', None) or getattr(culture, 'festivals', '')
            if not place.festivals_ne:
                place.festivals_ne = getattr(culture, 'festivals_ne', None) or place.festivals_en
            if not place.local_cuisine_en:
                place.local_cuisine_en = getattr(culture, 'cuisine_en', None) or getattr(culture, 'cuisine', '')
            if not place.local_cuisine_ne:
                place.local_cuisine_ne = getattr(culture, 'cuisine_ne', None) or place.local_cuisine_en
            if not place.traditions_en:
                place.traditions_en = getattr(culture, 'folkDance_en', None) or getattr(culture, 'folkDance', '')
            if not place.traditions_ne:
                place.traditions_ne = getattr(culture, 'folkDance_ne', None) or place.traditions_en
            if not place.languages_en:
                place.languages_en = getattr(culture, 'dialects_en', None) or getattr(culture, 'dialects', '')
            if not place.languages_ne:
                place.languages_ne = getattr(culture, 'dialects_ne', None) or place.languages_en

